    c: Any, m: Any, y: Any, k: Any
) -> Optional[Tuple[float, float, float, float]]:
    return _safe_float_quadruple(c, m, y, k)


def safe_rect_list(value: Any) -> Optional[Rect]:
    try:
        values = list(itertools.islice(value, 4))
    except TypeError:
        return None

    if len(values) != 4:
        return None

    return safe_rect(*values)


